#pragma once
#include "race_control.h"
#include "race_engine.h"
namespace pp {
struct NoticeboardEntryState { uint32_t raceEntryId,laps;Time lastLapTime;bool hasLap; constexpr NoticeboardEntryState(uint32_t id=0,uint32_t lap=0,Time time=0,bool present=false):raceEntryId(id),laps(lap),lastLapTime(time),hasLap(present){} };
struct NoticeboardState { SessionLifecycle lifecycle=SessionLifecycle::Ready;uint32_t raceEntryId=0,laps=0;Time lastLapTime=0,scheduledGo=0,pauseEffectiveAt=0,scheduledRestartAt=0;RestartMethod restartMethod=RestartMethod::None;bool hasLap=false;NoticeboardEntryState entries[2]{};uint8_t entryCount=0;bool deadHeat=false,raceIntegrityFaulted=false,resultValid=true;RaceIntegrityReason raceIntegrityReason=RaceIntegrityReason::None;bool resultSealed=false;Time winningTime=0,finishTime=0,fastestLap=0;};
class Noticeboard { public: Noticeboard(const RaceControlModule& c,const RaceEngineModule&e,const ActiveSessionDefinition&a):control_(c),engine_(e),active_(a){}void setSession(const SessionDefinition& d){definition_=&d;}NoticeboardState current()const{NoticeboardState s{};s.lifecycle=control_.state();s.scheduledGo=control_.scheduledGo();s.pauseEffectiveAt=control_.pauseEffectiveAt();s.scheduledRestartAt=control_.scheduledRestartAt();s.restartMethod=control_.restartMethod();s.entryCount=engine_.entryCount();for(uint8_t i=0;i<s.entryCount;i++){auto&e=engine_.entryState(i);s.entries[i]=NoticeboardEntryState{e.raceEntryId,e.laps,e.lastLapTime,e.hasLap};}if(s.entryCount){s.raceEntryId=s.entries[0].raceEntryId;s.laps=s.entries[0].laps;s.lastLapTime=s.entries[0].lastLapTime;s.hasLap=s.entries[0].hasLap;}s.deadHeat=engine_.deadHeat();s.raceIntegrityFaulted=control_.integrityFaulted();s.raceIntegrityReason=control_.integrityReason();s.resultValid=!s.raceIntegrityFaulted;const auto&r=engine_.completedResult();s.resultSealed=r.sealed;s.winningTime=r.winningTime;s.finishTime=r.finishTime;s.fastestLap=r.fastestLap;return s;} const RaceEngineModule::CompletedRaceResult& completedResult() const { return engine_.completedResult(); } private:const RaceControlModule&control_;const RaceEngineModule&engine_;const ActiveSessionDefinition&active_;const SessionDefinition*definition_=nullptr;};
}
